    {"id":"1f835bed-bbdb-8263-90e6-fecb8c0e0491","classlevel":"Lớp 5","subject":"Tiếng Việt","semester":"Học kỳ 2","topic":"8. Thế giới của chúng ta","lesson":"g5-vietnamese-hk2-end","name":"Ôn tập cuối năm học · Công dụng của dấu gạch ngang","question_type":"Trắc nghiệm","generator_key":"g5.vietnamese.dash","prompt_template":"{question}","config":{"lesson":"g5-vietnamese-hk2-end"}},
    {"id":"ed5fea81-0c02-8019-89d5-b1a632a8b25a","classlevel":"Lớp 5","subject":"Tiếng Việt","semester":"Học kỳ 2","topic":"8. Thế giới của chúng ta","lesson":"g5-vietnamese-hk2-end","name":"Ôn tập cuối năm học · Nghĩa gốc và nghĩa chuyển","question_type":"Trắc nghiệm","generator_key":"g5.vietnamese.polysemy","prompt_template":"{question}","config":{"lesson":"g5-vietnamese-hk2-end"}},
    {"id":"c50d1e60-5bb2-8440-b679-828374fc21d8","classlevel":"Lớp 5","subject":"Tiếng Việt","semester":"Học kỳ 2","topic":"8. Thế giới của chúng ta","lesson":"g5-vietnamese-hk2-end","name":"Ôn tập cuối năm học · Liên kết câu bằng từ ngữ thay thế","question_type":"Trắc nghiệm","generator_key":"g5.vietnamese.cohesionReplace","prompt_template":"{question}","config":{"lesson":"g5-vietnamese-hk2-end"}}
]
$grade5$::jsonb) AS seed(
    id uuid, classlevel text, subject text, semester text, topic text, lesson text,
    name text, question_type text, generator_key text, prompt_template text, config jsonb
);

-- Keep discovery and writes consistent if another session edits the catalog concurrently.
SET LOCAL lock_timeout = '5s';
LOCK TABLE public.question_templates IN SHARE ROW EXCLUSIVE MODE;

DO $validate$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM grade5_template_seed seed
        JOIN public.question_templates existing ON existing.id = seed.id
        WHERE (existing.classlevel, existing.generator_key, COALESCE(existing.lesson, existing.config->>'lesson'))
            IS DISTINCT FROM (seed.classlevel, seed.generator_key, seed.lesson)
    ) THEN
        RAISE EXCEPTION 'Grade 5 template UUID already belongs to a different template';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM grade5_template_seed seed
        JOIN public.question_templates existing
          ON existing.classlevel = seed.classlevel
         AND existing.generator_key = seed.generator_key
         AND COALESCE(existing.lesson, existing.config->>'lesson') = seed.lesson
        GROUP BY seed.id
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'Multiple existing Grade 5 templates match the same generator and lesson';
    END IF;
END;
$validate$;

UPDATE public.question_templates AS existing
SET name = seed.name,
    subject = seed.subject,
    semester = seed.semester,
    topic = seed.topic,
    lesson = seed.lesson,
    question_type = seed.question_type,
    prompt_template = seed.prompt_template,
    config = seed.config,
    updated_at = now()
FROM grade5_template_seed AS seed
WHERE existing.classlevel = seed.classlevel
  AND existing.generator_key = seed.generator_key
  AND COALESCE(existing.lesson, existing.config->>'lesson') = seed.lesson
  AND (existing.name, existing.subject, existing.semester, existing.topic, existing.lesson,
       existing.question_type, existing.prompt_template, existing.config)
      IS DISTINCT FROM
      (seed.name, seed.subject, seed.semester, seed.topic, seed.lesson,
       seed.question_type, seed.prompt_template, seed.config);

INSERT INTO public.question_templates (
    id, name, classlevel, subject, semester, topic, lesson,
    question_type, generator_key, prompt_template, config, is_active
)
SELECT seed.id, seed.name, seed.classlevel, seed.subject, seed.semester, seed.topic, seed.lesson,
       seed.question_type, seed.generator_key, seed.prompt_template, seed.config, true
FROM grade5_template_seed AS seed
WHERE NOT EXISTS (
    SELECT 1 FROM public.question_templates AS existing
    WHERE existing.classlevel = seed.classlevel
      AND existing.generator_key = seed.generator_key
      AND COALESCE(existing.lesson, existing.config->>'lesson') = seed.lesson
);

DO $verify$
BEGIN
    IF EXISTS (
        SELECT 1 FROM grade5_template_seed AS seed
        WHERE NOT EXISTS (
            SELECT 1 FROM public.question_templates AS existing
            WHERE (existing.classlevel, existing.generator_key, existing.lesson, existing.name, existing.subject,
                   existing.semester, existing.topic, existing.question_type, existing.prompt_template, existing.config)
                = (seed.classlevel, seed.generator_key, seed.lesson, seed.name, seed.subject, seed.semester,
                   seed.topic, seed.question_type, seed.prompt_template, seed.config)
        )
    ) THEN
        RAISE EXCEPTION 'Grade 5 template catalog verification failed';
    END IF;
END;
$verify$;

SELECT seed.subject, seed.semester, count(*) AS templates,
       count(*) FILTER (WHERE existing.is_active) AS active_templates
FROM grade5_template_seed AS seed
JOIN public.question_templates AS existing
  ON (existing.classlevel, existing.generator_key, existing.lesson) = (seed.classlevel, seed.generator_key, seed.lesson)
GROUP BY seed.subject, seed.semester
ORDER BY seed.subject, seed.semester;

COMMIT;
